({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const base = '/api/boveda/' + MEITI.obtenerTabla('configuracion_app');

  const soyAdmin = MEITI.soyDuenoDeLaApp() || MEITI.miRolEnLaApp() === 'admin';

  const [pestana, setPestana] = React.useState('ayuda');
  const [filas, setFilas] = React.useState([]);
  const [cargando, setCargando] = React.useState(true);
  const [aviso, setAviso] = React.useState(null);

  const VACIO = { titulo: '', cuerpo: '', tono: 'neutro' };
  const [editando, setEditando] = React.useState(null);
  const [forma, setForma] = React.useState(VACIO);
  const [abierto, setAbierto] = React.useState(false);

  const cargar = async () => {
    setCargando(true);
    const r = await MEITI.fetchDatos(base + '?ecosistema=' + eco);
    if (r.ok) setFilas(r.registros);
    setCargando(false);
  };

  React.useEffect(() => { cargar(); }, []);

  const cerrarFormulario = () => { setAbierto(false); setEditando(null); setForma(VACIO); };

  const guardar = async () => {
    if (!forma.titulo.trim()) { setAviso('Ponle un título antes de guardar.'); return; }
    const fila = editando || {};
    const cuerpo = {
      id: fila.id || (pestana + '_' + Date.now()),
      seccion: pestana,
      titulo: forma.titulo.trim(),
      cuerpo: forma.cuerpo,
      tono: forma.tono || 'neutro',
      orden: fila.orden != null ? fila.orden : filas.filter(f => f.seccion === pestana).length,
      fecha: fila.fecha || new Date().toISOString()
    };
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + (editando ? '&id=' + fila.id : ''), {
      method: editando ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(cuerpo)
    });
    if (r && r.ok === false) { setAviso('No se pudo guardar. Vuelve a intentarlo.'); return; }
    setAviso(null);
    cerrarFormulario();
    cargar();
  };

  const borrar = async (fila) => {
    if (!await MEITI.confirmar('¿Borrar "' + (fila.titulo || 'este registro') + '"?', { titulo: MEITI.t('delete_action', null, 'Borrar'), confirmar: MEITI.t('delete_confirm', null, 'Sí, borrar'), tono: 'peligro' })) return;
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + '&id=' + fila.id, { method: 'DELETE' });
    if (r && r.ok === false) { setAviso('No se pudo borrar. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const abrirEdicion = (fila) => {
    setEditando(fila);
    setForma({ titulo: fila.titulo || '', cuerpo: fila.cuerpo || '', tono: fila.tono || 'neutro' });
    setAbierto(true);
  };

  const deLaSeccion = filas.filter(f => (f.seccion || 'ayuda') === pestana);
  const visibles = pestana === 'ayuda'
    ? deLaSeccion.slice().sort((a, b) => (a.orden || 0) - (b.orden || 0))
    : deLaSeccion.slice().sort((a, b) => String(b.fecha || '').localeCompare(String(a.fecha || '')));

  const fechaLegible = (v) => {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(v || ''));
    if (!m) return '';
    const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
    return Number(m[3]) + ' ' + MESES[Number(m[2]) - 1] + ' ' + m[1];
  };

  const TONOS = [
    { value: 'neutro', label: MEITI.t('note_input', null, 'Nota') },
    { value: 'exito', label: MEITI.t('update_input', null, 'Actualización') },
    { value: 'alerta', label: MEITI.t('notice_input', null, 'Aviso') },
    { value: 'peligro', label: MEITI.t('error_input', null, 'Error') }
  ];
  const nombreDelTono = (t) => (TONOS.find(x => x.value === (t || 'neutro')) || TONOS[0]).label;

  const filaAyuda = (f) => (
    <div key={f.id} style={{ border: '1px solid ' + tema.colorPrimario + '22', borderRadius: '0.75rem', padding: '1rem', marginBottom: '0.75rem' }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '0.75rem' }}>
        <strong style={{ color: tema.texto }}>{f.titulo}</strong>
        {soyAdmin && (
          <div style={{ display: 'flex', gap: '0.25rem', flexShrink: 0 }}>
            <UI.Boton variante="fantasma" ariaLabel={MEITI.t('edit_action', null, "Editar")} onClick={() => abrirEdicion(f)}><i className="fa-solid fa-pen-to-square"></i></UI.Boton>
            <UI.Boton variante="fantasma-peligro" ariaLabel={MEITI.t('delete_action', null, "Borrar")} onClick={() => borrar(f)}><i className="fa-solid fa-trash-can"></i></UI.Boton>
          </div>
        )}
      </div>
      {f.cuerpo && <p style={{ color: tema.texto, opacity: 0.8, marginTop: '0.5rem', whiteSpace: 'pre-wrap' }}>{f.cuerpo}</p>}
    </div>
  );

  const filaBitacora = (f) => (
    <div key={f.id} style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '0.75rem', borderBottom: '1px solid ' + tema.colorPrimario + '18', padding: '0.6rem 0' }}>
      <div style={{ minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap' }}>
          <UI.Chip tono={f.tono || 'neutro'}>{nombreDelTono(f.tono)}</UI.Chip>
          <strong style={{ color: tema.texto }}>{f.titulo}</strong>
        </div>
        {f.cuerpo && <p style={{ color: tema.texto, opacity: 0.75, marginTop: '0.35rem', whiteSpace: 'pre-wrap' }}>{f.cuerpo}</p>}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexShrink: 0 }}>
        <span style={{ color: tema.texto, opacity: 0.5, fontSize: '0.75rem', whiteSpace: 'nowrap' }}>{fechaLegible(f.fecha)}</span>
        {soyAdmin && <UI.Boton variante="fantasma-peligro" ariaLabel={MEITI.t('delete_action', null, "Borrar")} onClick={() => borrar(f)}><i className="fa-solid fa-trash-can"></i></UI.Boton>}
      </div>
    </div>
  );

  return (
    <UI.Tarjeta>
      <h3 style={{ color: tema.texto, fontSize: '1.2rem', fontWeight: 'bold', marginBottom: '0.25rem' }}>{MEITI.t('configuration_title', null, "Configuración")}</h3>
      <p style={{ color: tema.texto, opacity: 0.6, fontSize: '0.75rem', marginBottom: '1rem' }}>{MEITI.t('app_guide_description', null, "Cómo se usa esta app, y qué le fue pasando.")}</p>

      {aviso && <UI.Aviso mensaje={aviso} tono="alerta" onCerrar={() => setAviso(null)} />}

      <UI.Pestanas
        pestanas={[{ id: 'ayuda', titulo: MEITI.t('help_title', null, 'Ayuda'), icono: 'fa-circle-question' }, { id: 'bitacora', titulo: MEITI.t('changelog_title', null, 'Bitácora'), icono: 'fa-clock-rotate-left' }]}
        activa={pestana}
        onCambio={(id) => { setPestana(id); cerrarFormulario(); }}
        className="mb-4"
      />

      {cargando ? (
        <p style={{ color: tema.texto, opacity: 0.6 }}>{MEITI.t('loading', null, "Cargando...")}</p>
      ) : visibles.length === 0 ? (
        <UI.EstadoVacio
          icono={pestana === 'ayuda' ? 'fa-book-open' : 'fa-clock-rotate-left'}
          mensaje={pestana === 'ayuda'
            ? (soyAdmin ? 'Todavía no hay guía de uso. Escribe la primera sección y quien entre después va a saber cómo usar la app.' : 'Todavía no hay una guía para esta app.')
            : 'Todavía no hay nada anotado. Acá van a aparecer las actualizaciones, los avisos y los errores de esta app.'}
        />
      ) : pestana === 'ayuda' ? (
        <div>{visibles.map(filaAyuda)}</div>
      ) : (
        <UI.ListaScrollable alto="26rem">{visibles.map(filaBitacora)}</UI.ListaScrollable>
      )}

      {soyAdmin && (
        <div style={{ marginTop: '1.25rem', paddingTop: '1rem', borderTop: '1px solid ' + tema.colorPrimario + '22' }}>
          {!abierto ? (
            <UI.Boton variante="secundario" onClick={() => setAbierto(true)}>
              <i className="fa-solid fa-plus"></i> {pestana === 'ayuda' ? 'Agregar una sección a la guía' : 'Anotar en la bitácora'}
            </UI.Boton>
          ) : (
            <div>
              <UI.Campo
                etiqueta={pestana === 'ayuda' ? 'Título de la sección' : 'Qué pasó'}
                valor={forma.titulo}
                onChange={(e) => setForma({ ...forma, titulo: e.target.value })}
                placeholder={pestana === 'ayuda' ? 'Cómo dar de alta un cliente' : 'Se actualizó el catálogo de precios'}
              />
              <div style={{ height: '0.75rem' }} />
              <UI.Campo
                etiqueta={pestana === 'ayuda' ? 'Explicación' : 'Detalle (opcional)'}
                tipo="textarea"
                filas={4}
                valor={forma.cuerpo}
                onChange={(e) => setForma({ ...forma, cuerpo: e.target.value })}
                placeholder={pestana === 'ayuda' ? 'Explícalo como se lo explicarías a alguien que abre la app por primera vez' : 'Qué se cambió y por qué'}
              />
              {pestana === 'bitacora' && (
                <div style={{ marginTop: '0.75rem' }}>
                  <UI.Campo etiqueta={MEITI.t('type_input', null, "Tipo")} tipo="select" valor={forma.tono} onChange={(e) => setForma({ ...forma, tono: e.target.value })} opciones={TONOS} />
                </div>
              )}
              <div style={{ height: '0.75rem' }} />
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <UI.Boton onClick={guardar}>{editando ? 'Guardar cambios' : 'Guardar'}</UI.Boton>
                <UI.Boton variante="secundario" onClick={cerrarFormulario}>{MEITI.t('cancel_button', null, "Cancelar")}</UI.Boton>
              </div>
            </div>
          )}
        </div>
      )}
    </UI.Tarjeta>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const base = '/api/boveda/' + MEITI.obtenerTabla('roles_usuarios_app');

  const [filas, setFilas] = React.useState([]);
  const [cargando, setCargando] = React.useState(true);
  const [nuevoId, setNuevoId] = React.useState('');
  const [nuevoRol, setNuevoRol] = React.useState('lector');
  const [aviso, setAviso] = React.useState(null);

  const cargar = async () => {
    setCargando(true);
    const resultado = await MEITI.fetchDatos(base + '?ecosistema=' + eco);
    if (resultado.ok) setFilas(resultado.registros);
    setCargando(false);
  };

  React.useEffect(() => { cargar(); }, []);

  const miFila = filas.find(f => f.usuario_id === miId);
  const soyDueno = MEITI.soyDuenoDeLaApp ? MEITI.soyDuenoDeLaApp() : false;
  const soyAdmin = soyDueno || (miFila ? miFila.rol === 'admin' : filas.length === 0);
  const cuantosAdmins = filas.filter(f => f.rol === 'admin').length;

  const volverseAdmin = async () => {
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: 'rol_' + Date.now(), usuario_id: miId, email_visible: miId.startsWith('email_') ? miId.replace('email_', '') : miId, rol: 'admin' })
    });
    if (r && r.ok === false) { setAviso('No se pudo completar la acción. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const agregarUsuario = async (e) => {
    e.preventDefault();
    if (!nuevoId.trim()) { setAviso('Falta el email del usuario.'); return; }
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: 'rol_' + Date.now(), usuario_id: 'email_' + nuevoId.trim().toLowerCase(), email_visible: nuevoId.trim(), rol: nuevoRol })
    });
    if (r && r.ok === false) { setAviso('No se pudo agregar el usuario. Vuelve a intentarlo.'); return; }
    setNuevoId('');
    setNuevoRol('lector');
    cargar();
  };

  const cambiarRol = async (fila, rolNuevo) => {
    if (fila.rol === 'admin' && rolNuevo !== 'admin' && cuantosAdmins <= 1) {
      setAviso('No puedes quitarle el rol de administrador al último que queda. Nombra antes a otro.');
      return;
    }
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: fila.id, usuario_id: fila.usuario_id, email_visible: fila.email_visible, rol: rolNuevo })
    });
    if (r && r.ok === false) { setAviso('No se pudo cambiar el rol. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const quitarUsuario = async (fila) => {
    if (fila.usuario_id === miId) { setAviso('No puedes quitarte a ti mismo.'); return; }
    if (fila.rol === 'admin' && cuantosAdmins <= 1) {
      setAviso('No puedes quitar al último administrador: la app quedaría sin nadie que pueda administrarla. Nombra antes a otro.');
      return;
    }
    if (!await MEITI.confirmar('¿Quitar a ' + (fila.email_visible || fila.usuario_id) + '?')) return;
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + '&id=' + fila.id, { method: 'DELETE' });
    if (r && r.ok === false) { setAviso('No se pudo quitar al usuario. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const columnas = [
    {
      clave: 'usuario',
      etiqueta: MEITI.t('user_column', null, "Usuario"),
      render: (f) => (
        <span>{f.email_visible || f.usuario_id}{f.usuario_id === miId ? ' (tú)' : ''}</span>
      )
    },
    {
      clave: 'rol',
      etiqueta: MEITI.t('role_column', null, "Rol"),
      render: (f) => (
        soyAdmin && f.usuario_id !== miId ? (
          <UI.Desplegable
            tamano="compacto"
            valor={f.rol}
            onCambio={(e) => cambiarRol(f, e.target.value)}
            opciones={[{ value: 'admin', label: MEITI.t('admin_role_option', null, 'admin') }, { value: 'editor', label: MEITI.t('editor_role_option', null, 'editor') }, { value: 'lector', label: MEITI.t('reader_role_option', null, 'lector') }]}
          />
        ) : (
          <UI.Chip tono={f.rol === 'admin' ? 'exito' : f.rol === 'editor' ? 'alerta' : 'neutro'}>{f.rol}</UI.Chip>
        )
      )
    }
  ];

  const accionesExtra = soyAdmin ? [
    {
      etiqueta: MEITI.t('remove_button', null, "Quitar"),
      icono: 'fa-user-slash',
      tono: 'peligro',
      onClick: (f) => quitarUsuario(f),
      condicion: (f) => f.usuario_id !== miId
    }
  ] : [];

  return (
    <UI.Tarjeta>
      <h3 style={{color: tema.texto, marginBottom: '0.5rem', fontSize: '1.2rem', fontWeight: 'bold'}}>{MEITI.t('panel_title', null, "Roles y permisos")}</h3>
      <p style={{color: tema.texto, opacity: 0.6, fontSize: '0.75rem', marginBottom: '1rem'}}>{MEITI.t('panel_subtitle', null, "Molde base del sistema — control de acceso de esta app.")}</p>

      {aviso && <UI.Aviso mensaje={aviso} tono="alerta" onCerrar={() => setAviso(null)} />}

      {cargando ? (
        <p style={{color: tema.texto}}>{MEITI.t('loading_state', null, "Cargando...")}</p>
      ) : filas.length === 0 ? (
        <div>
          <UI.EstadoVacio icono="fa-user-shield" mensaje={MEITI.t('empty_admins_message', null, "Todavía no hay administradores en esta app.")} />
          <UI.Boton onClick={volverseAdmin}>{MEITI.t('self_promote_button', null, "Volverme administrador")}</UI.Boton>
        </div>
      ) : (
        <UI.TablaDatos
          columnas={columnas}
          datos={filas}
          claveId="id"
          accionesExtra={accionesExtra}
          advertirAccionIncompleta={false}
        />
      )}

      {soyAdmin && filas.length > 0 && (
        <form onSubmit={agregarUsuario} style={{marginTop: '1.5rem', display: 'flex', gap: '0.75rem', alignItems: 'flex-end', flexWrap: 'wrap'}}>
          <div style={{flex: 1, minWidth: '180px'}}>
            <UI.Campo etiqueta={MEITI.t('add_user_label', null, "Agregar usuario (email)")} valor={nuevoId} onChange={(e) => setNuevoId(e.target.value)} placeholder={MEITI.t('email_placeholder', null, "persona@email.com")} />
          </div>
          <div style={{minWidth: '140px'}}>
            <UI.Campo etiqueta={MEITI.t('role_column', null, "Rol")} tipo="select" valor={nuevoRol} onChange={(e) => setNuevoRol(e.target.value)} opciones={[{value:'admin', label:MEITI.t('admin_role_option', null, 'admin')}, {value:'editor', label:MEITI.t('editor_role_option', null, 'editor')}, {value:'lector', label:MEITI.t('reader_role_option', null, 'lector')}]} />
          </div>
          <UI.Boton tipo="submit">{MEITI.t('add_button', null, "Agregar")}</UI.Boton>
        </form>
      )}
    </UI.Tarjeta>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();

  const [estado, setEstado] = React.useState(null);
  const [elegido, setElegido] = React.useState('');
  const [valores, setValores] = React.useState({});
  const [cargando, setCargando] = React.useState(true);
  const [guardando, setGuardando] = React.useState(false);
  const [error, setError] = React.useState('');
  const [aviso, setAviso] = React.useState('');

  const cargar = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatos(`/api/almacenamiento/estado?ecosistema=${eco}`);
    if (res.ok && res.registros && res.registros.length) {
      const d = res.registros[0];
      setEstado(d);
      setElegido(d.proveedor || (d.proveedores && d.proveedores[0] ? d.proveedores[0].id : ''));
      setValores(d.publica ? { ...d.publica } : {});
    } else {
      setError('No se pudo leer la configuración.');
    }
    setCargando(false);
  };

  React.useEffect(() => { cargar(); }, []);

  const proveedores = (estado && estado.proveedores) || [];
  const ficha = proveedores.find(p => p.id === elegido);

  const guardar = async () => {
    setGuardando(true); setError(''); setAviso('');
    const r = await MEITI.fetchMutante('/api/almacenamiento/guardar', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ecosistema: eco, proveedor: elegido, valores })
    });
    if (r.ok) { setAviso('Listo. Esta app ya puede guardar fotos, videos y documentos.'); await cargar(); }
    else { setError((r.datos && r.datos.error) || 'No se pudo guardar.'); }
    setGuardando(false);
  };

  const desconectar = async () => {
    if (!(await MEITI.confirmar('¿Desconectar la cuenta de archivos? Los archivos ya subidos siguen en tu proveedor.', { titulo: MEITI.t('disconnect_button', null, 'Desconectar'), confirmar: MEITI.t('disconnect_confirm', null, 'Sí, desconectar'), tono: 'peligro' }))) return;
    setGuardando(true); setError(''); setAviso('');
    const r = await MEITI.fetchMutante('/api/almacenamiento/borrar', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ecosistema: eco })
    });
    if (r.ok) { setAviso('Cuenta desconectada.'); setValores({}); await cargar(); }
    else { setError('No se pudo desconectar.'); }
    setGuardando(false);
  };

  if (cargando) return <UI.Tarjeta><p className="text-sm opacity-60">{MEITI.t('loading_config', null, "Cargando configuración...")}</p></UI.Tarjeta>;

  return (
    <UI.Tarjeta>
      <div className="flex items-center gap-2 mb-1">
        <i className="fa-solid fa-photo-film" style={{ color: tema.colorPrimario }}></i>
        <UI.Etiqueta>{MEITI.t('app_files_title', null, "Archivos de la app")}</UI.Etiqueta>
      </div>
      <p className="text-xs mb-4 leading-relaxed" style={{ opacity: 0.7 }}>
        {MEITI.t('storage_explanation', null, "Conecta tu cuenta de almacenamiento para que esta app pueda guardar fotos, videos o documentos. Los archivos viajan directo del navegador a tu cuenta: esta app guarda solo la dirección, nunca el archivo.")}
      </p>

      {estado && estado.configurado && (
        <div className="mb-3"><UI.Chip tono="exito">{MEITI.t('connected_with_label', null, "Conectado con")} {(proveedores.find(p => p.id === estado.proveedor) || {}).nombre || estado.proveedor}</UI.Chip></div>
      )}
      {aviso && <UI.Aviso mensaje={aviso} tono="exito" onCerrar={() => setAviso('')} />}
      {error && <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError('')} />}

      <div className="flex flex-col gap-3">
        <UI.Campo
          tipo="select"
          etiqueta={MEITI.t('provider_label', null, "Proveedor")}
          valor={elegido}
          onChange={(e) => { setElegido(e.target.value); setValores({}); }}
          opciones={proveedores.map(p => ({ value: p.id, label: p.nombre }))}
        />
        {ficha && ficha.ayuda && <p className="text-[11px] -mt-2" style={{ opacity: 0.55 }}>{ficha.ayuda}</p>}

        {(ficha ? ficha.campos : []).map(c => (
          <UI.Campo
            key={c.clave}
            tipo={c.secreto ? 'password' : 'text'}
            etiqueta={c.secreto ? `${c.etiqueta} (no se muestra nunca)` : c.etiqueta}
            valor={valores[c.clave] || ''}
            onChange={(e) => setValores(v => ({ ...v, [c.clave]: e.target.value }))}
            placeholder={c.secreto && estado && estado.configurado ? 'Guardado — escribe uno nuevo para cambiarlo' : ''}
          />
        ))}

        <div className="flex gap-2 flex-wrap">
          <UI.Boton onClick={guardar} disabled={guardando || !elegido}>
            {guardando ? 'Guardando...' : 'Guardar'}
          </UI.Boton>
          {estado && estado.configurado && (
            <UI.Boton variante="fantasma-peligro" onClick={desconectar} disabled={guardando}>{MEITI.t('disconnect_button', null, "Desconectar")}</UI.Boton>
          )}
        </div>
      </div>

      <p className="text-[11px] mt-4 pt-3" style={{ opacity: 0.5, borderTop: `1px solid ${tema.texto}1a` }}>
        {MEITI.t('deletion_warning', null, "Si borras un registro de la app, el archivo queda en tu cuenta: esta app no administra tu almacenamiento. Los borras desde tu proveedor cuando quieras.")}
      </p>
    </UI.Tarjeta>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();

  const [productos, setProductos] = useState([]);
  const [categorias, setCategorias] = useState([]);
  const [mediosPago, setMediosPago] = useState([]);
  const [turnoActivo, setTurnoActivo] = useState(null);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  const [catActiva, setCatActiva] = useState('todas');
  const [carrito, setCarrito] = useState([]);
  const [verCarrito, setVerCarrito] = useState(false);
  const [procesando, setProcesando] = useState(false);
  const [medioSeleccionado, setMedioSeleccionado] = useState('');
  const [pagoEfectivo, setPagoEfectivo] = useState('');

  const cargarDatos = async () => {
    setCargando(true);
    const [resProd, resCat, resMedios, resTurnos] = await Promise.all([
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_productos')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_categorias')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_medios_pago')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_caja_turnos')}?ecosistema=${eco}`)
    ]);

    if (resProd.ok) setProductos(resProd.registros.filter(p => String(p.disponible) === '1').map(p => ({...p, precio: Number(p.precio || 0)})).sort((a, b) => (a.orden || 0) - (b.orden || 0)));
    if (resCat.ok) setCategorias(resCat.registros.sort((a, b) => (a.orden || 0) - (b.orden || 0)));
    if (resMedios.ok) {
      const activos = resMedios.registros.filter(m => String(m.activo) === '1');
      setMediosPago(activos);
      if (activos.length > 0) setMedioSeleccionado(activos[0].nombre);
    }
    if (resTurnos.ok) {
      const abierto = resTurnos.registros.find(t => t.estado === 'abierto');
      setTurnoActivo(abierto || null);
    }
    setCargando(false);
  };

  useEffect(() => { cargarDatos(); }, []);

  const agregarAlCarrito = (prod) => {
    setCarrito(prev => {
      const existe = prev.find(i => i.producto_id === prod.id);
      if (existe) return prev.map(i => i.producto_id === prod.id ? { ...i, cantidad: i.cantidad + 1, subtotal: (i.cantidad + 1) * i.precio_unitario } : i);
      return [...prev, { producto_id: prod.id, nombre: prod.nombre, cantidad: 1, precio_unitario: prod.precio, subtotal: prod.precio }];
    });
  };

  const modificarCantidad = (id, delta) => {
    setCarrito(prev => {
      return prev.map(i => {
        if (i.producto_id === id) {
          const nuevaCant = Math.max(0, i.cantidad + delta);
          return { ...i, cantidad: nuevaCant, subtotal: nuevaCant * i.precio_unitario };
        }
        return i;
      }).filter(i => i.cantidad > 0);
    });
  };

  const totalCarrito = carrito.reduce((acc, item) => acc + item.subtotal, 0);
  const vuelto = parseFloat(pagoEfectivo) > totalCarrito ? parseFloat(pagoEfectivo) - totalCarrito : 0;

  const confirmarVenta = async () => {
    if (carrito.length === 0 || !turnoActivo || !medioSeleccionado) return;
    setProcesando(true);
    setError(null);

    const ventaId = 'vta_' + Date.now();
    const mutaciones = [
      {
        url: `/api/boveda/${MEITI.obtenerTabla('cg_ventas')}?ecosistema=${eco}`,
        opciones: {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            id: ventaId,
            autor_id: miId,
            turno_id: turnoActivo.id,
            total: totalCarrito,
            medio_pago: medioSeleccionado,
            estado: 'completada',
            fecha_registro: new Date().toISOString()
          })
        }
      },
      ...carrito.map(item => ({
        url: `/api/boveda/${MEITI.obtenerTabla('cg_venta_items')}?ecosistema=${eco}`,
        opciones: {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            id: 'vi_' + Date.now() + Math.random().toString(36).substring(7),
            venta_id: ventaId,
            producto_id: item.producto_id,
            cantidad: item.cantidad,
            precio_unitario: item.precio_unitario,
            subtotal: item.subtotal
          })
        }
      }))
    ];

    await MEITI.mutarVarias(mutaciones, {
      alLograr: () => {
        setCarrito([]);
        setVerCarrito(false);
        setPagoEfectivo('');
        setProcesando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('err_sale', null, 'Error al procesar la venta.'));
        setProcesando(false);
      }
    });
  };

  if (cargando) return <div className="p-8 text-center"><Iconos.LoaderCircle size={32} className="animate-spin mx-auto" color={tema.colorPrimario} /></div>;

  if (!turnoActivo) return (
    <UI.Tarjeta className="text-center py-12 flex flex-col items-center gap-4">
      <Iconos.Lock size={48} color={tema.colorSecundario} />
      <h2 className="text-2xl font-bold" style={{color: tema.texto}}>{MEITI.t('register_closed', null, 'La caja está cerrada')}</h2>
      <p className="opacity-70" style={{color: tema.texto}}>{MEITI.t('register_closed_desc', null, 'Debes abrir un turno de caja antes de poder registrar ventas.')}</p>
      <UI.Boton onClick={() => MEITI.irAPagina('caja')} variante="primario">{MEITI.t('go_to_register', null, 'Ir a Caja')}</UI.Boton>
    </UI.Tarjeta>
  );

  const prodsFiltrados = catActiva === 'todas' ? productos : productos.filter(p => p.categoria_id === catActiva);

  return (
    <div className="flex flex-col gap-4 pb-32">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <div className="flex gap-2 overflow-x-auto snap-x pb-2 px-1">
        <button
          onClick={() => setCatActiva('todas')}
          className="snap-start whitespace-nowrap px-5 py-2.5 rounded-full font-bold transition-all"
          style={{ background: catActiva === 'todas' ? tema.colorPrimario : tema.superficie, color: catActiva === 'todas' ? '#fff' : tema.texto, border: `1px solid ${tema.colorPrimario}33` }}
        >
          {MEITI.t('all_cats', null, 'Todas')}
        </button>
        {categorias.map(c => (
          <button
            key={c.id}
            onClick={() => setCatActiva(c.id)}
            className="snap-start whitespace-nowrap px-5 py-2.5 rounded-full font-bold transition-all"
            style={{ background: catActiva === c.id ? tema.colorPrimario : tema.superficie, color: catActiva === c.id ? '#fff' : tema.texto, border: `1px solid ${tema.colorPrimario}33` }}
          >
            {c.nombre}
          </button>
        ))}
      </div>

      {prodsFiltrados.length === 0 ? (
        <UI.EstadoVacio icono="fa-mug-hot" mensaje={MEITI.t('no_products', null, 'No hay productos en esta categoría.')} />
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
          {prodsFiltrados.map(p => (
            <button 
              key={p.id} 
              onClick={() => agregarAlCarrito(p)}
              className="flex flex-col items-center text-center p-3 rounded-2xl transition-transform active:scale-95 shadow-sm"
              style={{ background: tema.superficie, border: `1px solid ${tema.texto}11` }}
            >
              <div className="w-16 h-16 rounded-xl mb-2 overflow-hidden bg-black/5 flex items-center justify-center">
                {p.imagen_url ? <img src={p.imagen_url} alt={p.nombre} className="w-full h-full object-cover" /> : <Iconos.Coffee size={24} color={tema.colorPrimario} />}
              </div>
              <span className="font-bold text-sm leading-tight line-clamp-2" style={{color: tema.texto}}>{p.nombre}</span>
              <span className="font-black mt-1" style={{color: tema.colorSecundario}}>${p.precio.toFixed(2)}</span>
            </button>
          ))}
        </div>
      )}

      {carrito.length > 0 && (
        <div className="fixed bottom-24 inset-x-4 z-30">
          <button 
            onClick={() => setVerCarrito(true)}
            className="w-full py-4 rounded-2xl font-black text-lg shadow-2xl flex items-center justify-between px-6"
            style={{ background: tema.colorSecundario, color: '#fff' }}
          >
            <div className="flex items-center gap-3">
              <div className="bg-white/20 px-3 py-1 rounded-full text-sm">{carrito.reduce((a, b) => a + b.cantidad, 0)}</div>
              <span>{MEITI.t('view_ticket', null, 'Ver Ticket')}</span>
            </div>
            <span>${totalCarrito.toFixed(2)}</span>
          </button>
        </div>
      )}

      <Animacion.AnimatePresence>
        {verCarrito && (
          <>
            <Animacion.motion.div 
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/60 z-40"
              onClick={() => setVerCarrito(false)}
            />
            <Animacion.motion.div 
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 200 }}
              className="fixed bottom-0 inset-x-0 z-50 rounded-t-3xl flex flex-col shadow-2xl max-h-[85vh]"
              style={{ background: tema.fondo }}
            >
              <div className="p-4 flex justify-center shrink-0">
                <div className="w-12 h-1.5 rounded-full opacity-20" style={{ background: tema.texto }} />
              </div>

              <div className="px-6 pb-4 flex justify-between items-center shrink-0 border-b" style={{ borderColor: tema.texto + '11' }}>
                <h2 className="text-2xl font-black" style={{ color: tema.texto }}>{MEITI.t('current_ticket', null, 'Ticket en Curso')}</h2>
                <button onClick={() => setCarrito([])} className="text-sm font-bold text-red-500">{MEITI.t('clear_all', null, 'Vaciar')}</button>
              </div>

              <div className="flex-1 overflow-y-auto p-6 flex flex-col gap-4">
                {carrito.map(item => (
                  <div key={item.producto_id} className="flex items-center justify-between">
                    <div className="flex-1">
                      <div className="font-bold" style={{ color: tema.texto }}>{item.nombre}</div>
                      <div className="text-sm opacity-70" style={{ color: tema.texto }}>${item.precio_unitario.toFixed(2)} c/u</div>
                    </div>
                    <div className="flex items-center gap-3">
                      <button onClick={() => modificarCantidad(item.producto_id, -1)} className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: tema.superficie, color: tema.texto, border: `1px solid ${tema.texto}22` }}><Iconos.Minus size={16} /></button>
                      <span className="font-black w-6 text-center" style={{ color: tema.texto }}>{item.cantidad}</span>
                      <button onClick={() => modificarCantidad(item.producto_id, 1)} className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: tema.colorPrimario, color: '#fff' }}><Iconos.Plus size={16} /></button>
                    </div>
                    <div className="w-20 text-right font-bold" style={{ color: tema.texto }}>${item.subtotal.toFixed(2)}</div>
                  </div>
                ))}
              </div>

              <div className="p-6 shrink-0 rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.1)]" style={{ background: tema.superficie }}>
                <div className="flex justify-between items-center mb-4">
                  <span className="text-lg font-bold opacity-70" style={{ color: tema.texto }}>{MEITI.t('total', null, 'Total')}</span>
                  <span className="text-3xl font-black" style={{ color: tema.colorPrimario }}>${totalCarrito.toFixed(2)}</span>
                </div>

                <div className="mb-4">
                  <UI.Etiqueta>{MEITI.t('payment_method', null, 'Medio de Pago')}</UI.Etiqueta>
                  <div className="flex gap-2 overflow-x-auto snap-x pb-2 mt-2">
                    {mediosPago.map(m => (
                      <button
                        key={m.id}
                        onClick={() => setMedioSeleccionado(m.nombre)}
                        className="snap-start whitespace-nowrap px-4 py-2 rounded-xl font-bold transition-all"
                        style={{ background: medioSeleccionado === m.nombre ? tema.colorSecundario : tema.fondo, color: medioSeleccionado === m.nombre ? '#fff' : tema.texto, border: `1px solid ${tema.colorSecundario}44` }}
                      >
                        {m.nombre}
                      </button>
                    ))}
                  </div>
                </div>

                {String(medioSeleccionado || '').toLowerCase().includes('efectivo') && (
                  <div className="mb-6 flex gap-4 items-end">
                    <div className="flex-1">
                      <UI.Campo etiqueta={MEITI.t('cash_received', null, 'Efectivo Recibido')} tipo="number" valor={pagoEfectivo} onChange={e => setPagoEfectivo(e.target.value)} placeholder="0.00" />
                    </div>
                    <div className="flex-1 p-3 rounded-xl text-center" style={{ background: vuelto > 0 ? '#10b98122' : tema.fondo, border: `1px solid ${vuelto > 0 ? '#10b981' : tema.texto + '22'}` }}>
                      <div className="text-xs font-bold opacity-70 uppercase" style={{ color: tema.texto }}>{MEITI.t('change', null, 'Vuelto')}</div>
                      <div className="font-black text-lg" style={{ color: vuelto > 0 ? '#10b981' : tema.texto }}>${vuelto.toFixed(2)}</div>
                    </div>
                  </div>
                )}

                <button 
                  onClick={confirmarVenta}
                  disabled={procesando || carrito.length === 0}
                  className="w-full py-4 rounded-2xl font-black text-xl flex items-center justify-center gap-2"
                  style={{ background: tema.colorPrimario, color: '#fff', opacity: procesando ? 0.7 : 1 }}
                >
                  <Iconos.CheckCircle size={24} />
                  {procesando ? MEITI.t('processing', null, 'Procesando...') : MEITI.t('confirm_sale', null, 'Cobrar Ticket')}
                </button>
              </div>
            </Animacion.motion.div>
          </>
        )}
      </Animacion.AnimatePresence>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();

  const [turnoActivo, setTurnoActivo] = useState(null);
  const [ventas, setVentas] = useState([]);
  const [movimientos, setMovimientos] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  const [montoApertura, setMontoApertura] = useState('');
  const [montoCierre, setMontoCierre] = useState('');

  const [verModalMov, setVerModalMov] = useState(false);
  const [formMov, setFormMov] = useState({ tipo: 'retiro', monto: '', concepto: '' });

  const cargarDatos = async () => {
    setCargando(true);
    const resTurnos = await MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_caja_turnos')}?ecosistema=${eco}`);

    if (resTurnos.ok) {
      const abierto = resTurnos.registros.find(t => t.estado === 'abierto');
      setTurnoActivo(abierto || null);

      if (abierto) {
        const [resVentas, resMovs] = await Promise.all([
          MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_ventas')}?ecosistema=${eco}`),
          MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_caja_movimientos')}?ecosistema=${eco}`)
        ]);
        if (resVentas.ok) setVentas(resVentas.registros.filter(v => v.turno_id === abierto.id && v.estado === 'completada'));
        if (resMovs.ok) setMovimientos(resMovs.registros.filter(m => m.turno_id === abierto.id));
      }
    }
    setCargando(false);
  };

  useEffect(() => { cargarDatos(); }, []);

  const abrirCaja = async () => {
    if (montoApertura === '' || isNaN(parseFloat(montoApertura))) return setError(MEITI.t('err_open_amount', null, 'Ingresa un monto inicial válido.'));
    setError(null);

    const payload = {
      id: 'turno_' + Date.now(),
      autor_id: miId,
      fecha_apertura: new Date().toISOString(),
      monto_apertura: parseFloat(montoApertura),
      estado: 'abierto'
    };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('cg_caja_turnos')}?ecosistema=${eco}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { setMontoApertura(''); cargarDatos(); },
      alFallar: setError
    });
  };

  const registrarMovimiento = async () => {
    if (!formMov.monto || isNaN(parseFloat(formMov.monto)) || !formMov.concepto.trim()) return setError(MEITI.t('err_mov_fields', null, 'Completa monto y concepto.'));
    setError(null);

    const payload = {
      id: 'mov_' + Date.now(),
      autor_id: miId,
      turno_id: turnoActivo.id,
      tipo: formMov.tipo,
      monto: parseFloat(formMov.monto),
      concepto: formMov.concepto.trim(),
      fecha_registro: new Date().toISOString()
    };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('cg_caja_movimientos')}?ecosistema=${eco}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { setVerModalMov(false); setFormMov({ tipo: 'retiro', monto: '', concepto: '' }); cargarDatos(); },
      alFallar: setError
    });
  };

  const cerrarCaja = async () => {
    if (montoCierre === '' || isNaN(parseFloat(montoCierre))) return setError(MEITI.t('err_close_amount', null, 'Ingresa el monto real en caja.'));
    if (!await MEITI.confirmar(MEITI.t('confirm_close_q', null, '¿Estás seguro de cerrar la caja? Ya no podrás registrar ventas en este turno.'))) return;
    setError(null);

    const payload = {
      ...turnoActivo,
      estado: 'cerrado',
      fecha_cierre: new Date().toISOString(),
      monto_cierre_real: parseFloat(montoCierre)
    };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('cg_caja_turnos')}?ecosistema=${eco}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { setMontoCierre(''); cargarDatos(); },
      alFallar: setError
    });
  };

  if (cargando) return <div className="p-8 text-center"><Iconos.LoaderCircle size={32} className="animate-spin mx-auto" color={tema.colorPrimario} /></div>;

  if (!turnoActivo) return (
    <div className="flex flex-col gap-6 pb-28">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
      <UI.Tarjeta className="text-center py-12 flex flex-col items-center gap-6">
        <div className="w-24 h-24 rounded-full flex items-center justify-center bg-black/5">
          <Iconos.KeyRound size={48} color={tema.colorPrimario} />
        </div>
        <div>
          <h2 className="text-3xl font-black" style={{color: tema.texto}}>{MEITI.t('open_register', null, 'Apertura de Caja')}</h2>
          <p className="opacity-70 mt-2" style={{color: tema.texto}}>{MEITI.t('open_register_desc', null, 'Ingresa el monto de cambio inicial para comenzar el turno.')}</p>
        </div>
        <div className="w-full max-w-xs">
          <UI.Campo etiqueta={MEITI.t('initial_cash', null, 'Fondo de Caja Inicial ($)')} tipo="number" valor={montoApertura} onChange={e => setMontoApertura(e.target.value)} placeholder="0.00" />
        </div>
        <UI.Boton onClick={abrirCaja} variante="primario" className="w-full max-w-xs py-4 text-lg">{MEITI.t('btn_open_register', null, 'Abrir Turno')}</UI.Boton>
      </UI.Tarjeta>
    </div>
  );

  const ventasEfectivo = ventas.filter(v => (v.medio_pago || '').toLowerCase().includes('efectivo')).reduce((acc, v) => acc + v.total, 0);
  const ventasOtros = ventas.filter(v => !(v.medio_pago || '').toLowerCase().includes('efectivo')).reduce((acc, v) => acc + v.total, 0);
  const ingresos = movimientos.filter(m => m.tipo === 'ingreso').reduce((acc, m) => acc + m.monto, 0);
  const retiros = movimientos.filter(m => m.tipo === 'retiro').reduce((acc, m) => acc + m.monto, 0);
  const efectivoEsperado = turnoActivo.monto_apertura + ventasEfectivo + ingresos - retiros;

  return (
    <div className="flex flex-col gap-6 pb-32">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <UI.Tarjeta className="p-6 flex flex-col gap-2" style={{ background: tema.colorPrimario, color: '#fff' }}>
          <span className="font-bold opacity-80 uppercase tracking-wider text-sm">{MEITI.t('expected_cash', null, 'Efectivo Esperado en Caja')}</span>
          <span className="text-5xl font-black">${efectivoEsperado.toFixed(2)}</span>
          <div className="text-sm opacity-90 mt-2">
            {MEITI.t('initial', null, 'Inicial')}: ${turnoActivo.monto_apertura.toFixed(2)} | {MEITI.t('cash_sales', null, 'Ventas Ef.')}: ${ventasEfectivo.toFixed(2)}
          </div>
        </UI.Tarjeta>

        <UI.Tarjeta className="p-6 flex flex-col gap-2">
          <span className="font-bold opacity-70 uppercase tracking-wider text-sm" style={{color: tema.texto}}>{MEITI.t('other_sales', null, 'Ventas Tarjeta / QR')}</span>
