({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const [ventas, setVentas] = useState([]);
  const [items, setItems] = useState([]);
  const [productos, setProductos] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  const [detalleVenta, setDetalleVenta] = useState(null);
  const [verAnular, setVerAnular] = useState(false);
  const [motivoAnulacion, setMotivoAnulacion] = useState('');

  const cargarDatos = async () => {
    setCargando(true);
    const [resVentas, resItems, resProd] = await Promise.all([
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_ventas')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_venta_items')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_productos')}?ecosistema=${eco}`)
    ]);

    if (resVentas.ok) setVentas([...resVentas.registros].sort((a, b) => new Date(b.fecha_registro) - new Date(a.fecha_registro)));
    if (resItems.ok) setItems(resItems.registros);
    if (resProd.ok) setProductos(resProd.registros);
    setCargando(false);
  };

  useEffect(() => { cargarDatos(); }, []);

  const anularVenta = async () => {
    if (!motivoAnulacion.trim()) return setError(MEITI.t('err_void_reason', null, 'Debes ingresar un motivo para la anulación.'));
    setError(null);

    const payload = {
      ...detalleVenta,
      estado: 'anulada',
      motivo_anulacion: motivoAnulacion.trim()
    };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('cg_ventas')}?ecosistema=${eco}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setVerAnular(false);
        setDetalleVenta(null);
        setMotivoAnulacion('');
        cargarDatos();
      },
      alFallar: setError
    });
  };

  const columnas = [
    { clave: 'id', etiqueta: MEITI.t('ticket_id', null, 'Ticket'), render: f => <span className="font-mono font-bold">#{f.id.slice(-6)}</span> },
    { clave: 'fecha_registro', etiqueta: MEITI.t('time', null, 'Hora'), render: f => new Date(f.fecha_registro).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) },
    { clave: 'total', etiqueta: MEITI.t('total', null, 'Total'), tipo: 'moneda' },
    { clave: 'medio_pago', etiqueta: MEITI.t('payment', null, 'Pago') },
    { clave: 'estado', etiqueta: MEITI.t('status', null, 'Estado'), render: f => <UI.Chip tono={f.estado === 'completada' ? 'exito' : 'peligro'}>{f.estado.toUpperCase()}</UI.Chip> }
  ];

  const accionesExtra = [
    {
      etiqueta: MEITI.t('view_details', null, 'Ver Detalle'),
      icono: 'fa-eye',
      tono: 'neutro',
      onClick: (f) => setDetalleVenta(f)
    }
  ];

  if (cargando) return <div className="p-8 text-center"><Iconos.LoaderCircle size={32} className="animate-spin mx-auto" color={tema.colorPrimario} /></div>;

  return (
    <div className="flex flex-col gap-6 pb-28">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <UI.Tarjeta>
        <div className="flex items-center gap-3 mb-4">
          <Iconos.ReceiptText size={24} color={tema.colorPrimario} />
          <UI.Etiqueta>{MEITI.t('sales_history', null, 'Historial de Tickets')}</UI.Etiqueta>
        </div>
        {ventas.length === 0 ? (
          <UI.EstadoVacio icono="fa-receipt" mensaje={MEITI.t('no_sales', null, 'No hay ventas registradas aún.')} />
        ) : (
          <UI.TablaDatos columnas={columnas} datos={ventas} claveId="id" accionesExtra={accionesExtra} advertirAccionIncompleta={false} />
        )}
      </UI.Tarjeta>

      <Animacion.AnimatePresence>
        {detalleVenta && (
          <>
            <Animacion.motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-black/60 z-40" onClick={() => { setDetalleVenta(null); setVerAnular(false); }} />
            <Animacion.motion.div initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 200 }} className="fixed bottom-0 inset-x-0 z-50 rounded-t-3xl p-6 flex flex-col gap-4 shadow-2xl max-h-[85vh] overflow-y-auto" style={{ background: tema.fondo }}>
              <div className="w-12 h-1.5 rounded-full mx-auto opacity-20 mb-2 shrink-0" style={{ background: tema.texto }} />

              <div className="flex justify-between items-start">
                <div>
                  <h3 className="text-2xl font-black" style={{color: tema.texto}}>{MEITI.t('ticket_details', null, 'Detalle del Ticket')}</h3>
                  <p className="font-mono opacity-70" style={{color: tema.texto}}>#{detalleVenta.id}</p>
                </div>
                <UI.Chip tono={detalleVenta.estado === 'completada' ? 'exito' : 'peligro'}>{detalleVenta.estado.toUpperCase()}</UI.Chip>
              </div>

              <div className="p-4 rounded-xl flex flex-col gap-3 my-2" style={{ background: tema.superficie }}>
                {items.filter(i => i.venta_id === detalleVenta.id).map(item => {
                  const prod = productos.find(p => p.id === item.producto_id);
                  return (
                    <div key={item.id} className="flex justify-between items-center border-b pb-2 last:border-0 last:pb-0" style={{ borderColor: tema.texto + '11' }}>
                      <div className="flex items-center gap-3">
                        <span className="font-black" style={{color: tema.colorPrimario}}>{item.cantidad}x</span>
                        <span style={{color: tema.texto}}>{prod ? prod.nombre : 'Producto Eliminado'}</span>
                      </div>
                      <span className="font-bold" style={{color: tema.texto}}>${item.subtotal.toFixed(2)}</span>
                    </div>
                  );
                })}
              </div>

              <div className="flex justify-between items-center p-4 rounded-xl" style={{ background: tema.colorPrimario, color: '#fff' }}>
                <span className="text-lg font-bold">{MEITI.t('total', null, 'Total')}</span>
                <span className="text-3xl font-black">${detalleVenta.total.toFixed(2)}</span>
              </div>

              <div className="text-sm opacity-70 text-center" style={{color: tema.texto}}>
                {MEITI.t('paid_with', null, 'Pagado con')}: <strong>{detalleVenta.medio_pago}</strong><br/>
                {new Date(detalleVenta.fecha_registro).toLocaleString()}
              </div>

              {detalleVenta.estado === 'anulada' && (
                <div className="p-4 rounded-xl mt-2" style={{ background: '#ef444422', color: '#ef4444', border: '1px solid #ef4444' }}>
                  <strong>{MEITI.t('void_reason', null, 'Motivo de anulación')}:</strong> {detalleVenta.motivo_anulacion}
                </div>
              )}

              {detalleVenta.estado === 'completada' && !verAnular && (
                <UI.Boton onClick={() => setVerAnular(true)} variante="peligro" className="mt-4 py-3">{MEITI.t('btn_void_ticket', null, 'Anular Ticket')}</UI.Boton>
              )}

              {verAnular && (
                <div className="p-4 rounded-xl mt-4 flex flex-col gap-3 border-2" style={{ borderColor: '#ef4444', background: tema.superficie }}>
                  <UI.Etiqueta>{MEITI.t('confirm_void', null, 'Confirmar Anulación')}</UI.Etiqueta>
                  <UI.Campo etiqueta={MEITI.t('reason', null, 'Motivo')} tipo="text" valor={motivoAnulacion} onChange={e => setMotivoAnulacion(e.target.value)} placeholder={MEITI.t('ph_reason', null, 'Ej: Error de carga, cliente canceló')} />
                  <div className="flex gap-2 mt-2">
                    <div className="flex-1"><UI.Boton onClick={anularVenta} variante="peligro" className="w-full">{MEITI.t('confirm', null, 'Confirmar')}</UI.Boton></div>
                    <div className="flex-1"><UI.Boton onClick={() => setVerAnular(false)} variante="secundario" className="w-full">{MEITI.t('cancel', null, 'Cancelar')}</UI.Boton></div>
                  </div>
                </div>
              )}
            </Animacion.motion.div>
          </>
        )}
      </Animacion.AnimatePresence>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const [ventas, setVentas] = useState([]);
  const [items, setItems] = useState([]);
  const [productos, setProductos] = useState([]);
  const [cargando, setCargando] = useState(true);

  useEffect(() => {
    const cargar = async () => {
      const [resVentas, resItems, resProd] = await Promise.all([
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_ventas')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_venta_items')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_productos')}?ecosistema=${eco}`)
      ]);
      if (resVentas.ok) setVentas(resVentas.registros.filter(v => v.estado === 'completada'));
      if (resItems.ok) setItems(resItems.registros);
      if (resProd.ok) setProductos(resProd.registros);
      setCargando(false);
    };
    cargar();
  }, []);

  if (cargando) return <div className="p-8 text-center"><i className="fa-solid fa-spinner fa-spin mx-auto" style={{ fontSize: '32px', color: tema.colorPrimario }}></i></div>;

  const hoyStr = new Date().toISOString().split('T')[0];
  const ventasHoy = ventas.filter(v => (v.fecha_registro || '').startsWith(hoyStr));
  const totalHoy = ventasHoy.reduce((acc, v) => acc + v.total, 0);
  const ticketPromedio = ventasHoy.length > 0 ? totalHoy / ventasHoy.length : 0;

  const ultimos7Dias = [...Array(7)].map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return d.toISOString().split('T')[0];
  }).reverse();

  const datosGraficoDias = ultimos7Dias.map(fecha => {
    const total = ventas.filter(v => (v.fecha_registro || '').startsWith(fecha)).reduce((acc, v) => acc + v.total, 0);
    return { fecha: fecha.slice(5), total };
  });

  const conteoProductos = {};
  items.forEach(item => {
    const v = ventas.find(v => v.id === item.venta_id);
    if (v) {
      conteoProductos[item.producto_id] = (conteoProductos[item.producto_id] || 0) + item.cantidad;
    }
  });
  const topProductos = Object.entries(conteoProductos)
    .map(([id, cant]) => ({ nombre: productos.find(p => p.id === id)?.nombre || 'Desc.', cantidad: cant }))
    .sort((a, b) => b.cantidad - a.cantidad)
    .slice(0, 5);

  return (
    <div className="flex flex-col gap-6 pb-28">
      <div className="grid grid-cols-2 gap-4">
        <UI.Tarjeta className="p-5 flex flex-col gap-2" style={{ background: tema.colorPrimario, color: '#fff' }}>
          <i className="fa-solid fa-arrow-trend-up" style={{ fontSize: '24px', opacity: 0.8 }}></i>
          <span className="font-bold opacity-90 text-sm">{MEITI.t('sales_today', null, 'Ventas Hoy')}</span>
          <span className="text-3xl font-black">${totalHoy.toFixed(0)}</span>
        </UI.Tarjeta>
        <UI.Tarjeta className="p-5 flex flex-col gap-2" style={{ background: tema.colorSecundario, color: '#fff' }}>
          <i className="fa-solid fa-receipt" style={{ fontSize: '24px', opacity: 0.8 }}></i>
          <span className="font-bold opacity-90 text-sm">{MEITI.t('avg_ticket', null, 'Ticket Promedio')}</span>
          <span className="text-3xl font-black">${ticketPromedio.toFixed(0)}</span>
        </UI.Tarjeta>
      </div>

      <UI.Tarjeta>
        <UI.Etiqueta>{MEITI.t('last_7_days', null, 'Ventas últimos 7 días')}</UI.Etiqueta>
        {ventas.length === 0 ? (
          <UI.EstadoVacio icono="fa-chart-line" mensaje={MEITI.t('no_data_chart', null, 'No hay datos suficientes para graficar.')} />
        ) : (
          <div className="w-full h-64 mt-4">
            <Graficos.ResponsiveContainer width="100%" height="100%">
              <Graficos.BarChart data={datosGraficoDias}>
                <Graficos.CartesianGrid strokeDasharray="3 3" vertical={false} stroke={tema.texto + '22'} />
                <Graficos.XAxis dataKey="fecha" stroke={tema.texto} fontSize={12} tickLine={false} axisLine={false} />
                <Graficos.Tooltip cursor={{fill: tema.texto+'11'}} contentStyle={{borderRadius:'12px', border:'none', boxShadow:'0 4px 20px rgba(0,0,0,0.1)'}} />
                <Graficos.Bar dataKey="total" fill={tema.colorPrimario} radius={[4, 4, 0, 0]} />
              </Graficos.BarChart>
            </Graficos.ResponsiveContainer>
          </div>
        )}
      </UI.Tarjeta>

      <UI.Tarjeta>
        <UI.Etiqueta>{MEITI.t('top_products', null, 'Productos más vendidos')}</UI.Etiqueta>
        {topProductos.length === 0 ? (
          <UI.EstadoVacio icono="fa-star" mensaje={MEITI.t('no_top_products', null, 'Aún no hay productos vendidos.')} />
        ) : (
          <div className="flex flex-col gap-3 mt-4">
            {topProductos.map((p, i) => (
              <div key={i} className="flex items-center justify-between p-3 rounded-xl" style={{ background: tema.fondo }}>
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full flex items-center justify-center font-black text-sm" style={{ background: tema.colorSecundario + '22', color: tema.colorSecundario }}>{i+1}</div>
                  <span className="font-bold" style={{color: tema.texto}}>{p.nombre}</span>
                </div>
                <span className="font-black" style={{color: tema.texto}}>{p.cantidad} u.</span>
              </div>
            ))}
          </div>
        )}
      </UI.Tarjeta>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();

  const [productos, setProductos] = useState([]);
  const [categorias, setCategorias] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const vacio = { id: '', nombre: '', categoria_id: '', precio: '', imagen_url: '', disponible: '1' };
  const [form, setForm] = useState(vacio);
  const [verForm, setVerForm] = useState(false);
  const [guardando, setGuardando] = useState(false);

  const cargarDatos = async () => {
    setCargando(true);
    const [resProd, resCat] = await Promise.all([
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_productos')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_categorias')}?ecosistema=${eco}`)
    ]);
    if (resProd.ok) setProductos(resProd.registros.sort((a,b) => (a.orden||0)-(b.orden||0)));
    if (resCat.ok) setCategorias(resCat.registros);
    setCargando(false);
  };

  useEffect(() => { cargarDatos(); }, []);

  const subirFoto = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const r = await MEITI.subirArchivo(file);
    if (r.ok) setForm({ ...form, imagen_url: r.url });
    else setError(r.motivo || MEITI.t('err_upload', null, 'Error al subir imagen.'));
  };

  const guardar = async (e) => {
    e.preventDefault();
    if (!form.nombre.trim() || !form.categoria_id || !form.precio) return setError(MEITI.t('err_req_fields', null, 'Nombre, categoría y precio son obligatorios.'));
    setError(null); setExito(null); setGuardando(true);

    const payload = {
      id: form.id || 'prod_' + Date.now(),
      autor_id: miId,
      nombre: form.nombre.trim(),
      categoria_id: form.categoria_id,
      precio: parseFloat(form.precio),
      imagen_url: form.imagen_url,
      disponible: parseInt(form.disponible),
      orden: form.id ? form.orden : productos.length
    };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('cg_productos')}?ecosistema=${eco}`, {
      method: form.id ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('saved_success', null, 'Producto guardado.'));
        setForm(vacio);
        setVerForm(false);
        cargarDatos();
        setGuardando(false);
      },
      alFallar: (err) => { setError(err); setGuardando(false); }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('confirm_delete_prod', null, '¿Borrar este producto del catálogo?'))) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('cg_productos')}?ecosistema=${eco}&id=${id}`, { method: 'DELETE' }, {
      alLograr: cargarDatos,
      alFallar: setError
    });
  };

  const editar = (fila) => {
    setForm({ id: fila.id, nombre: fila.nombre, categoria_id: fila.categoria_id, precio: String(fila.precio), imagen_url: fila.imagen_url || '', disponible: String(fila.disponible), orden: fila.orden });
    setVerForm(true);
  };

  const columnas = [
    { clave: 'imagen_url', etiqueta: 'Img', render: f => f.imagen_url ? <img src={f.imagen_url} className="w-10 h-10 rounded-lg object-cover" /> : <div className="w-10 h-10 rounded-lg bg-black/10 flex items-center justify-center"><i className="fa-solid fa-mug-hot" style={{ fontSize: '16px', opacity: 0.5 }}></i></div> },
    { clave: 'nombre', etiqueta: MEITI.t('name', null, 'Nombre'), render: f => <span className="font-bold">{f.nombre}</span> },
    { clave: 'precio', etiqueta: MEITI.t('price', null, 'Precio'), tipo: 'moneda' },
    { clave: 'disponible', etiqueta: MEITI.t('status', null, 'Estado'), render: f => <UI.Chip tono={String(f.disponible)==='1' ? 'exito' : 'neutro'}>{String(f.disponible)==='1' ? 'Activo' : 'Pausado'}</UI.Chip> }
  ];

  if (cargando) return <div className="p-8 text-center"><i className="fa-solid fa-spinner fa-spin mx-auto" style={{ fontSize: '32px', color: tema.colorPrimario }}></i></div>;

  return (
    <div className="flex flex-col gap-6 pb-28">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
      <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

      <UI.Tarjeta>
        <div className="flex justify-between items-center mb-4">
          <UI.Etiqueta>{MEITI.t('catalog', null, 'Catálogo de Productos')}</UI.Etiqueta>
          <UI.Boton onClick={() => { setForm(vacio); setVerForm(true); }} variante="primario">+ {MEITI.t('new', null, 'Nuevo')}</UI.Boton>
        </div>
        {productos.length === 0 ? (
          <UI.EstadoVacio icono="fa-box-open" mensaje={MEITI.t('no_products_yet', null, 'No hay productos cargados.')} />
        ) : (
          <UI.TablaDatos columnas={columnas} datos={productos} claveId="id" onEditar={editar} onBorrar={(f) => borrar(f.id)} />
