      <Animacion.AnimatePresence>
        {verForm && (
          <>
            <Animacion.motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-black/60 z-40" onClick={() => setVerForm(false)} />
            <Animacion.motion.div initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 200 }} className="fixed bottom-0 inset-x-0 z-50 rounded-t-3xl p-6 flex flex-col gap-4 shadow-2xl max-h-[90vh] overflow-y-auto" style={{ background: tema.fondo }}>
              <div className="w-12 h-1.5 rounded-full mx-auto opacity-20 mb-2 shrink-0" style={{ background: tema.texto }} />
              <h3 className="text-2xl font-black" style={{color: tema.texto}}>{form.id ? MEITI.t('edit_product', null, 'Editar Producto') : MEITI.t('new_product', null, 'Nuevo Producto')}</h3>

              <form onSubmit={guardar} className="flex flex-col gap-4">
                <div className="flex items-center gap-4 p-4 rounded-2xl" style={{ background: tema.superficie }}>
                  <div className="w-20 h-20 rounded-xl bg-black/5 overflow-hidden flex items-center justify-center shrink-0">
                    {form.imagen_url ? <img src={form.imagen_url} className="w-full h-full object-cover" /> : <i className="fa-solid fa-image" style={{ fontSize: '24px', opacity: 0.5 }}></i>}
                  </div>
                  <div className="flex-1">
                    <label className="block text-sm font-bold mb-2" style={{color: tema.texto}}>{MEITI.t('photo', null, 'Foto del producto')}</label>
                    <input type="file" accept="image/*" onChange={subirFoto} className="text-sm w-full" />
                  </div>
                </div>

                <UI.Campo etiqueta={MEITI.t('name', null, 'Nombre')} tipo="text" valor={form.nombre} onChange={e => setForm({...form, nombre: e.target.value})} />

                <div className="grid grid-cols-2 gap-4">
                  <UI.Campo etiqueta={MEITI.t('price', null, 'Precio ($)')} tipo="number" valor={form.precio} onChange={e => setForm({...form, precio: e.target.value})} />
                  <UI.Campo etiqueta={MEITI.t('category', null, 'Categoría')} tipo="select" valor={form.categoria_id} onChange={e => setForm({...form, categoria_id: e.target.value})} opciones={[{value:'', label: MEITI.t('select', null, 'Seleccionar...')}, ...categorias.map(c => ({value: c.id, label: c.nombre}))]} />
                </div>

                <UI.Campo etiqueta={MEITI.t('status', null, 'Disponibilidad')} tipo="select" valor={form.disponible} onChange={e => setForm({...form, disponible: e.target.value})} opciones={[{value:'1', label: MEITI.t('available', null, 'Disponible')}, {value:'0', label: MEITI.t('unavailable', null, 'Agotado / Oculto')}]} />

                <UI.Boton tipo="submit" variante="primario" className="py-4 mt-2" disabled={guardando}>{guardando ? MEITI.t('saving', null, 'Guardando...') : MEITI.t('save', null, 'Guardar Producto')}</UI.Boton>
              </form>
            </Animacion.motion.div>
          </>
        )}
      </Animacion.AnimatePresence>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const [turnos, setTurnos] = useState([]);
  const [ventas, setVentas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  const esAdmin = MEITI.miRolEnLaApp() === 'admin' || MEITI.soyDuenoDeLaApp();

  const cargarDatos = async () => {
    if (!esAdmin) return;
    setCargando(true);
    const eco = MEITI.obtenerEcosistemaActual();
    const [resTurnos, resVentas] = await Promise.all([
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_caja_turnos')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_ventas')}?ecosistema=${eco}`)
    ]);

    if (!resTurnos.ok || !resVentas.ok) {
      setError(resTurnos.error || resVentas.error || MEITI.t('err_load_data', null, 'Error al cargar los datos.'));
    } else {
      setTurnos(resTurnos.registros || []);
      setVentas(resVentas.registros || []);
    }
    setCargando(false);
  };

  useEffect(() => {
    cargarDatos();
  }, []);

  if (!esAdmin) return <UI.Aviso tono="alerta" mensaje={MEITI.t('admin_only', null, 'Esta sección es solo para administradores.')} />;

  if (cargando) return <UI.Tarjeta><div className="p-8 text-center"><Iconos.LoaderCircle className="animate-spin mx-auto mb-4" size={32} color={tema.colorPrimario} /><UI.Etiqueta>{MEITI.t('loading_stats', null, 'Calculando estadísticas...')}</UI.Etiqueta></div></UI.Tarjeta>;

  const ventasValidas = ventas.filter(v => v.estado !== 'anulada');
  const totalVendido = ventasValidas.reduce((acc, v) => acc + (Number(v.total) || 0), 0);
  const turnosCerrados = turnos.filter(t => t.estado === 'cerrado');

  let descuadreTotal = 0;
  turnosCerrados.forEach(t => {
    const ventasDelTurno = ventasValidas.filter(v => v.turno_id === t.id).reduce((acc, v) => acc + (Number(v.total) || 0), 0);
    const esperado = (Number(t.monto_apertura) || 0) + ventasDelTurno;
    descuadreTotal += (Number(t.monto_cierre_real) || 0) - esperado;
  });

  const ventasPorCajero = ventasValidas.reduce((acc, v) => {
    const cajero = v.autor_id || 'Desconocido';
    acc[cajero] = (acc[cajero] || 0) + (Number(v.total) || 0);
    return acc;
  }, {});

  const datosGrafico = Object.keys(ventasPorCajero).map(c => ({
    nombre: c.split('@')[0],
    ventas: ventasPorCajero[c]
  })).sort((a, b) => b.ventas - a.ventas);

  return (
    <div className="flex flex-col gap-6">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-6">
            <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ backgroundColor: tema.colorPrimario + '22', color: tema.colorPrimario }}>
              <Iconos.Banknote size={28} />
            </div>
            <div>
              <UI.Etiqueta>{MEITI.t('total_sales', null, 'Ventas Totales')}</UI.Etiqueta>
              <div className="text-2xl font-black font-mono" style={{ color: tema.texto }}>${totalVendido.toFixed(2)}</div>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>

        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-6">
            <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ backgroundColor: tema.colorSecundario + '22', color: tema.colorSecundario }}>
              <Iconos.History size={28} />
            </div>
            <div>
              <UI.Etiqueta>{MEITI.t('total_shifts', null, 'Turnos Registrados')}</UI.Etiqueta>
              <div className="text-2xl font-black font-mono" style={{ color: tema.texto }}>{turnos.length}</div>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>

        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.2 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-6">
            <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ backgroundColor: (descuadreTotal < 0 ? '#ef4444' : '#10b981') + '22', color: descuadreTotal < 0 ? '#ef4444' : '#10b981' }}>
              <Iconos.Scale size={28} />
            </div>
            <div>
              <UI.Etiqueta>{MEITI.t('total_diff', null, 'Descuadre Histórico')}</UI.Etiqueta>
              <div className="text-2xl font-black font-mono" style={{ color: descuadreTotal < 0 ? '#ef4444' : '#10b981' }}>
                {descuadreTotal > 0 ? '+' : ''}${descuadreTotal.toFixed(2)}
              </div>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
      </div>

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.3 }}>
        <UI.Tarjeta>
          <div className="flex items-center gap-2 mb-6">
            <Iconos.ChartColumn size={20} color={tema.colorPrimario} />
            <h3 className="font-bold text-lg" style={{ color: tema.texto }}>{MEITI.t('sales_by_cashier', null, 'Ventas por Cajero')}</h3>
          </div>

          {datosGrafico.length === 0 ? (
            <UI.EstadoVacio icono="fa-chart-simple" mensaje={MEITI.t('no_sales_chart', null, 'Todavía no hay ventas registradas para graficar.')} />
          ) : (
            <div className="w-full h-80">
              <Graficos.ResponsiveContainer width="100%" height="100%">
                <Graficos.BarChart data={datosGrafico} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                  <Graficos.CartesianGrid strokeDasharray="3 3" stroke={tema.texto + '22'} vertical={false} />
                  <Graficos.XAxis dataKey="nombre" stroke={tema.texto} fontSize={12} tickLine={false} axisLine={false} />
                  <Graficos.YAxis stroke={tema.texto} fontSize={12} tickLine={false} axisLine={false} tickFormatter={(val) => `$${val}`} />
                  <Graficos.Tooltip 
                    cursor={{ fill: tema.texto + '11' }}
                    contentStyle={{ backgroundColor: tema.superficie, borderColor: tema.colorPrimario + '44', borderRadius: '8px', color: tema.texto }}
                    itemStyle={{ color: tema.colorPrimario, fontWeight: 'bold' }}
                    formatter={(value) => [`$${value.toFixed(2)}`, MEITI.t('sales', null, 'Ventas')]}
                  />
                  <Graficos.Bar dataKey="ventas" fill={tema.colorPrimario} radius={[4, 4, 0, 0]} />
                </Graficos.BarChart>
              </Graficos.ResponsiveContainer>
            </div>
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const [turnos, setTurnos] = useState([]);
  const [ventas, setVentas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const [editando, setEditando] = useState(null);
  const [form, setForm] = useState({ id: '', monto_cierre_real: '', estado: '' });

  const esAdmin = MEITI.miRolEnLaApp() === 'admin' || MEITI.soyDuenoDeLaApp();
  const eco = MEITI.obtenerEcosistemaActual();
  const urlTurnos = `/api/boveda/${MEITI.obtenerTabla('cg_caja_turnos')}?ecosistema=${eco}`;

  const cargarDatos = async () => {
    if (!esAdmin) return;
    setCargando(true);
    const [resTurnos, resVentas] = await Promise.all([
      MEITI.fetchDatos(urlTurnos),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('cg_ventas')}?ecosistema=${eco}`)
    ]);

    if (!resTurnos.ok || !resVentas.ok) {
      setError(resTurnos.error || resVentas.error || MEITI.t('err_load_shifts', null, 'Error al cargar el historial.'));
    } else {
      setTurnos(resTurnos.registros || []);
      setVentas(resVentas.registros || []);
    }
    setCargando(false);
  };

  useEffect(() => {
    cargarDatos();
  }, []);

  if (!esAdmin) return <UI.Aviso tono="alerta" mensaje={MEITI.t('admin_only', null, 'Esta sección es solo para administradores.')} />;

  const guardarEdicion = async (e) => {
    e.preventDefault();
    setError(null);
    setExito(null);

    const turnoOriginal = turnos.find(t => t.id === form.id);
    if (!turnoOriginal) return;

    const payload = {
      ...turnoOriginal,
      monto_cierre_real: Number(form.monto_cierre_real),
      estado: form.estado
    };

    await MEITI.mutar(urlTurnos, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('shift_updated', null, 'Turno actualizado correctamente.'));
        setEditando(null);
        cargarDatos();
      },
      alFallar: (err) => setError(err || MEITI.t('err_update_shift', null, 'No se pudo actualizar el turno.'))
    });
  };

  const borrarTurno = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('confirm_delete_shift', null, '¿Borrar este registro de turno? Las ventas asociadas no se borrarán, pero perderán su referencia de caja.'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;

    setError(null);
    setExito(null);

    await MEITI.mutar(`${urlTurnos}&id=${id}`, {
      method: 'DELETE'
    }, {
      alLograr: () => {
        setExito(MEITI.t('shift_deleted', null, 'Turno eliminado.'));
        if (editando === id) setEditando(null);
        cargarDatos();
      },
      alFallar: (err) => setError(err || MEITI.t('err_delete_shift', null, 'No se pudo eliminar el turno.'))
    });
  };

  const abrirEdicion = (fila) => {
    setEditando(fila.id);
    setForm({
      id: fila.id,
      monto_cierre_real: fila.monto_cierre_real !== null ? String(fila.monto_cierre_real) : '',
      estado: fila.estado || 'abierto'
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const turnosEnriquecidos = turnos.map(t => {
    const ventasDelTurno = ventas.filter(v => v.turno_id === t.id && v.estado !== 'anulada');
    const totalVendido = ventasDelTurno.reduce((sum, v) => sum + (Number(v.total) || 0), 0);
    const esperado = (Number(t.monto_apertura) || 0) + totalVendido;
    const diferencia = t.estado === 'cerrado' ? (Number(t.monto_cierre_real) || 0) - esperado : 0;

    return {
      ...t,
      total_vendido: totalVendido,
      diferencia: diferencia
    };
  }).sort((a, b) => new Date(b.fecha_apertura || 0) - new Date(a.fecha_apertura || 0));

  const columnas = [
    { clave: 'fecha_apertura', etiqueta: MEITI.t('col_open_date', null, 'Apertura'), tipo: 'fecha' },
    { clave: 'autor_id', etiqueta: MEITI.t('col_cashier', null, 'Cajero'), render: (f) => <span className="opacity-80">{f.autor_id?.split('@')[0] || '---'}</span> },
    { clave: 'monto_apertura', etiqueta: MEITI.t('col_base', null, 'Base'), tipo: 'moneda' },
    { clave: 'total_vendido', etiqueta: MEITI.t('col_sales', null, 'Ventas'), tipo: 'moneda' },
    { clave: 'monto_cierre_real', etiqueta: MEITI.t('col_real_close', null, 'Cierre Real'), render: (f) => f.estado === 'cerrado' ? `$${(Number(f.monto_cierre_real)||0).toFixed(2)}` : '---' },
    { clave: 'diferencia', etiqueta: MEITI.t('col_diff', null, 'Diferencia'), render: (f) => {
      if (f.estado !== 'cerrado') return <span className="opacity-50">---</span>;
      const color = f.diferencia < 0 ? '#ef4444' : f.diferencia > 0 ? '#10b981' : tema.texto;
      return <span className="font-mono font-bold" style={{ color }}>{f.diferencia > 0 ? '+' : ''}${f.diferencia.toFixed(2)}</span>;
    }},
    { clave: 'estado', etiqueta: MEITI.t('col_status', null, 'Estado'), render: (f) => (
      <UI.Chip tono={f.estado === 'abierto' ? 'exito' : 'neutro'}>{f.estado?.toUpperCase()}</UI.Chip>
    )}
  ];

  return (
    <div className="flex flex-col gap-6">
      <Animacion.AnimatePresence>
        {editando && (
          <Animacion.motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
            <UI.Tarjeta className="mb-2">
              <div className="flex items-center gap-2 mb-4">
                <Iconos.Pencil size={20} color={tema.colorPrimario} />
                <UI.Etiqueta>{MEITI.t('edit_shift', null, 'Corregir Turno')}</UI.Etiqueta>
              </div>
              <form onSubmit={guardarEdicion} className="flex flex-col gap-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="flex-1">
                    <UI.Campo 
                      etiqueta={MEITI.t('f_real_close', null, 'Monto Cierre Real')}
                      tipo="number"
                      valor={form.monto_cierre_real}
                      onChange={(e) => setForm({...form, monto_cierre_real: e.target.value})}
                    />
                  </div>
                  <div className="flex-1">
                    <UI.Campo 
                      etiqueta={MEITI.t('f_status', null, 'Estado del Turno')}
                      tipo="select"
                      valor={form.estado}
                      onChange={(e) => setForm({...form, estado: e.target.value})}
                      opciones={[{value: 'abierto', label: MEITI.t('opt_open', null, 'Abierto')}, {value: 'cerrado', label: MEITI.t('opt_closed', null, 'Cerrado')}]}
                    />
                  </div>
                </div>
                <div className="flex gap-2">
                  <UI.Boton tipo="submit" variante="primario">
                    <span className="flex items-center gap-2"><Iconos.Save size={16} /> {MEITI.t('btn_save', null, 'Guardar Cambios')}</span>
                  </UI.Boton>
                  <UI.Boton tipo="button" variante="secundario" onClick={() => setEditando(null)}>
                    <span className="flex items-center gap-2"><Iconos.X size={16} /> {MEITI.t('btn_cancel', null, 'Cancelar')}</span>
                  </UI.Boton>
                </div>
              </form>
            </UI.Tarjeta>
          </Animacion.motion.div>
        )}
      </Animacion.AnimatePresence>

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
        <UI.Tarjeta className="flex flex-col gap-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Iconos.ListChecks size={20} color={tema.colorSecundario} />
              <UI.Etiqueta>{MEITI.t('shift_history', null, 'Historial de Turnos')}</UI.Etiqueta>
            </div>
            <UI.Boton onClick={cargarDatos} variante="secundario" ariaLabel={MEITI.t('refresh', null, 'Actualizar')}>
              <Iconos.RefreshCw size={16} />
            </UI.Boton>
          </div>

          <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
          <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

          {cargando ? (
            <div className="p-8 text-center"><Iconos.LoaderCircle className="animate-spin mx-auto mb-4" size={32} color={tema.colorPrimario} /><UI.Etiqueta>{MEITI.t('loading_shifts', null, 'Cargando historial...')}</UI.Etiqueta></div>
          ) : turnosEnriquecidos.length === 0 ? (
            <UI.EstadoVacio icono="fa-cash-register" mensaje={MEITI.t('no_shifts', null, 'Todavía no hay turnos registrados en la caja.')} />
          ) : (
            <UI.TablaDatos 
              columnas={columnas} 
              datos={turnosEnriquecidos} 
              claveId="id" 
              onEditar={abrirEdicion} 
              onBorrar={(fila) => borrarTurno(fila.id)} 
            />
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const esAdmin = MEITI.miRolEnLaApp() === 'admin' || MEITI.soyDuenoDeLaApp();

  const PESTANAS = [
    { id: 'categorias', titulo: MEITI.t('tab_categories', null, 'Categorías'), icono: 'fa-tags', tabla: 'cg_categorias' },
    { id: 'medios_pago', titulo: MEITI.t('tab_payments', null, 'Medios de Pago'), icono: 'fa-credit-card', tabla: 'cg_medios_pago' },
    { id: 'motivos_anulacion', titulo: MEITI.t('tab_voids', null, 'Motivos Anulación'), icono: 'fa-ban', tabla: 'cg_motivos_anulacion' },
    { id: 'descuentos', titulo: MEITI.t('tab_discounts', null, 'Descuentos'), icono: 'fa-percent', tabla: 'cg_descuentos' }
  ];

  const [pestanaActiva, setPestanaActiva] = useState('categorias');
  const [registros, setRegistros] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const [form, setForm] = useState({});
  const [editando, setEditando] = useState(false);

  const cargarDatos = async () => {
    if (!esAdmin) return;
    setCargando(true);
    const tab = PESTANAS.find(p => p.id === pestanaActiva);
    const url = `/api/boveda/${MEITI.obtenerTabla(tab.tabla)}?ecosistema=${MEITI.obtenerEcosistemaActual()}`;

    const res = await MEITI.fetchDatos(url);
    if (res.ok) {
      let data = res.registros || [];
      if (pestanaActiva === 'categorias') data = data.sort((a, b) => (Number(a.orden) || 0) - (Number(b.orden) || 0));
      setRegistros(data);
    } else {
      setError(res.error || MEITI.t('err_load_catalog', null, 'Error al cargar el catálogo.'));
    }
    setCargando(false);
  };

  useEffect(() => {
    cargarDatos();
    setForm({});
    setEditando(false);
    setError(null);
    setExito(null);
  }, [pestanaActiva]);

  if (!esAdmin) return <UI.Aviso tono="alerta" mensaje={MEITI.t('admin_only', null, 'Esta sección es solo para administradores.')} />;

  const guardar = async (e) => {
    e.preventDefault();
    setError(null);
    setExito(null);

    if (pestanaActiva === 'categorias' && !form.nombre) return setError(MEITI.t('err_req_name', null, 'El nombre es obligatorio.'));
    if (pestanaActiva === 'medios_pago' && !form.nombre) return setError(MEITI.t('err_req_name', null, 'El nombre es obligatorio.'));
    if (pestanaActiva === 'motivos_anulacion' && !form.motivo) return setError(MEITI.t('err_req_reason', null, 'El motivo es obligatorio.'));
    if (pestanaActiva === 'descuentos' && !form.nombre) return setError(MEITI.t('err_req_name', null, 'El nombre es obligatorio.'));

    setGuardando(true);
    const tab = PESTANAS.find(p => p.id === pestanaActiva);
    const url = `/api/boveda/${MEITI.obtenerTabla(tab.tabla)}?ecosistema=${MEITI.obtenerEcosistemaActual()}`;

    let payload = { ...form, autor_id: MEITI.obtenerUsuarioActual() };
    if (!editando) {
      payload.id = `${pestanaActiva}_${Date.now()}`;
    }

    if (pestanaActiva === 'categorias') payload.orden = Number(payload.orden) || 0;
    if (pestanaActiva === 'medios_pago') {
      payload.requiere_comprobante = Number(payload.requiere_comprobante ?? 0);
      payload.activo = Number(payload.activo ?? 1);
    }
    if (pestanaActiva === 'motivos_anulacion') payload.activo = Number(payload.activo ?? 1);
    if (pestanaActiva === 'descuentos') {
      payload.porcentaje = Number(payload.porcentaje) || 0;
      payload.activo = Number(payload.activo ?? 1);
    }

    await MEITI.mutar(url, {
      method: editando ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('save_success', null, 'Registro guardado correctamente.'));
        setForm({});
        setEditando(false);
        cargarDatos();
        setGuardando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('save_error', null, 'Error al guardar el registro.'));
        setGuardando(false);
      }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('confirm_delete_cat', null, '¿Borrar este registro del catálogo?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;

    setError(null);
    setExito(null);
    const tab = PESTANAS.find(p => p.id === pestanaActiva);
    const url = `/api/boveda/${MEITI.obtenerTabla(tab.tabla)}?ecosistema=${MEITI.obtenerEcosistemaActual()}&id=${id}`;

    await MEITI.mutar(url, { method: 'DELETE' }, {
      alLograr: () => {
        setExito(MEITI.t('delete_success', null, 'Registro eliminado.'));
        if (form.id === id) {
          setForm({});
          setEditando(false);
        }
        cargarDatos();
      },
      alFallar: (err) => setError(err || MEITI.t('delete_error', null, 'Error al eliminar el registro.'))
    });
  };

  const abrirEdicion = (fila) => {
    setForm({ ...fila });
    setEditando(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cancelarEdicion = () => {
    setForm({});
    setEditando(false);
    setError(null);
    setExito(null);
  };

  const renderFormulario = () => {
    if (pestanaActiva === 'categorias') {
      return (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_name', null, 'Nombre')} tipo="text" valor={form.nombre || ''} onChange={e => setForm({...form, nombre: e.target.value})} placeholder={MEITI.t('ph_cat_name', null, 'Ej: Bebidas Calientes')} />
          </div>
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_color', null, 'Color (Hex)')} tipo="text" valor={form.color || ''} onChange={e => setForm({...form, color: e.target.value})} placeholder="#FF0000" />
          </div>
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_order', null, 'Orden')} tipo="number" valor={form.orden || ''} onChange={e => setForm({...form, orden: e.target.value})} placeholder="1" />
          </div>
        </div>
      );
    }
    if (pestanaActiva === 'medios_pago') {
      return (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_name', null, 'Nombre')} tipo="text" valor={form.nombre || ''} onChange={e => setForm({...form, nombre: e.target.value})} placeholder={MEITI.t('ph_pay_name', null, 'Ej: Tarjeta de Crédito')} />
          </div>
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_req_receipt', null, 'Requiere Comprobante')} tipo="select" valor={String(form.requiere_comprobante ?? '0')} onChange={e => setForm({...form, requiere_comprobante: e.target.value})} opciones={[{value:'1', label:MEITI.t('yes', null, 'Sí')}, {value:'0', label:MEITI.t('no', null, 'No')}]} />
          </div>
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_active', null, 'Activo')} tipo="select" valor={String(form.activo ?? '1')} onChange={e => setForm({...form, activo: e.target.value})} opciones={[{value:'1', label:MEITI.t('yes', null, 'Sí')}, {value:'0', label:MEITI.t('no', null, 'No')}]} />
          </div>
        </div>
      );
    }
    if (pestanaActiva === 'motivos_anulacion') {
      return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_reason', null, 'Motivo')} tipo="text" valor={form.motivo || ''} onChange={e => setForm({...form, motivo: e.target.value})} placeholder={MEITI.t('ph_reason', null, 'Ej: Error de tipeo')} />
          </div>
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_active', null, 'Activo')} tipo="select" valor={String(form.activo ?? '1')} onChange={e => setForm({...form, activo: e.target.value})} opciones={[{value:'1', label:MEITI.t('yes', null, 'Sí')}, {value:'0', label:MEITI.t('no', null, 'No')}]} />
          </div>
        </div>
      );
    }
    if (pestanaActiva === 'descuentos') {
      return (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_name', null, 'Nombre')} tipo="text" valor={form.nombre || ''} onChange={e => setForm({...form, nombre: e.target.value})} placeholder={MEITI.t('ph_disc_name', null, 'Ej: Empleado')} />
          </div>
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_percent', null, 'Porcentaje (%)')} tipo="number" valor={form.porcentaje || ''} onChange={e => setForm({...form, porcentaje: e.target.value})} placeholder="15" />
          </div>
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('f_active', null, 'Activo')} tipo="select" valor={String(form.activo ?? '1')} onChange={e => setForm({...form, activo: e.target.value})} opciones={[{value:'1', label:MEITI.t('yes', null, 'Sí')}, {value:'0', label:MEITI.t('no', null, 'No')}]} />
          </div>
        </div>
      );
    }
    return null;
  };

  const obtenerColumnas = () => {
    if (pestanaActiva === 'categorias') return [
      { clave: 'nombre', etiqueta: MEITI.t('col_name', null, 'Nombre') },
      { clave: 'color', etiqueta: MEITI.t('col_color', null, 'Color'), render: (f) => <div className="flex items-center gap-2"><div className="w-6 h-6 rounded-full border" style={{backgroundColor: f.color || 'transparent', borderColor: tema.texto+'33'}}></div><span className="opacity-70 font-mono text-xs">{f.color || '---'}</span></div> },
      { clave: 'orden', etiqueta: MEITI.t('col_order', null, 'Orden') }
    ];
    if (pestanaActiva === 'medios_pago') return [
      { clave: 'nombre', etiqueta: MEITI.t('col_name', null, 'Nombre') },
      { clave: 'requiere_comprobante', etiqueta: MEITI.t('col_req_receipt', null, 'Req. Comprobante'), render: (f) => <UI.Chip tono={Number(f.requiere_comprobante) === 1 ? 'exito' : 'neutro'}>{Number(f.requiere_comprobante) === 1 ? MEITI.t('yes', null, 'Sí') : MEITI.t('no', null, 'No')}</UI.Chip> },
      { clave: 'activo', etiqueta: MEITI.t('col_active', null, 'Activo'), render: (f) => <UI.Chip tono={Number(f.activo) === 1 ? 'exito' : 'peligro'}>{Number(f.activo) === 1 ? MEITI.t('yes', null, 'Sí') : MEITI.t('no', null, 'No')}</UI.Chip> }
    ];
    if (pestanaActiva === 'motivos_anulacion') return [
      { clave: 'motivo', etiqueta: MEITI.t('col_reason', null, 'Motivo') },
      { clave: 'activo', etiqueta: MEITI.t('col_active', null, 'Activo'), render: (f) => <UI.Chip tono={Number(f.activo) === 1 ? 'exito' : 'peligro'}>{Number(f.activo) === 1 ? MEITI.t('yes', null, 'Sí') : MEITI.t('no', null, 'No')}</UI.Chip> }
    ];
    if (pestanaActiva === 'descuentos') return [
      { clave: 'nombre', etiqueta: MEITI.t('col_name', null, 'Nombre') },
      { clave: 'porcentaje', etiqueta: MEITI.t('col_percent', null, 'Porcentaje'), render: (f) => <span className="font-bold" style={{color: tema.colorSecundario}}>{f.porcentaje}%</span> },
      { clave: 'activo', etiqueta: MEITI.t('col_active', null, 'Activo'), render: (f) => <UI.Chip tono={Number(f.activo) === 1 ? 'exito' : 'peligro'}>{Number(f.activo) === 1 ? MEITI.t('yes', null, 'Sí') : MEITI.t('no', null, 'No')}</UI.Chip> }
    ];
    return [];
  };

  return (
    <div className="flex flex-col gap-6">
      <UI.Pestanas pestanas={PESTANAS} activa={pestanaActiva} onCambio={setPestanaActiva} />

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }} key={`form-${pestanaActiva}`}>
        <UI.Tarjeta>
          <div className="flex items-center gap-2 mb-4">
            <Iconos.Settings2 size={20} color={tema.colorPrimario} />
            <UI.Etiqueta>{editando ? MEITI.t('edit_record', null, 'Editar Registro') : MEITI.t('new_record', null, 'Nuevo Registro')}</UI.Etiqueta>
          </div>

          <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
          <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

          <form onSubmit={guardar} className="flex flex-col gap-4">
            {renderFormulario()}
            <div className="flex gap-2 mt-2">
              <UI.Boton tipo="submit" variante="primario" disabled={guardando}>
                <span className="flex items-center gap-2">
                  <Iconos.Save size={16} /> 
                  {guardando ? MEITI.t('saving', null, 'Guardando...') : (editando ? MEITI.t('btn_update', null, 'Actualizar') : MEITI.t('btn_create', null, 'Crear Registro'))}
                </span>
              </UI.Boton>
              {editando && (
                <UI.Boton tipo="button" variante="secundario" onClick={cancelarEdicion}>
                  <span className="flex items-center gap-2"><Iconos.X size={16} /> {MEITI.t('btn_cancel', null, 'Cancelar')}</span>
                </UI.Boton>
              )}
            </div>
          </form>
        </UI.Tarjeta>
      </Animacion.motion.div>

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }} key={`list-${pestanaActiva}`}>
        <UI.Tarjeta className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <Iconos.List size={20} color={tema.colorSecundario} />
            <UI.Etiqueta>{MEITI.t('catalog_list', null, 'Registros del Catálogo')}</UI.Etiqueta>
          </div>

          {cargando ? (
            <div className="p-8 text-center">
              <Iconos.LoaderCircle className="animate-spin mx-auto mb-4" size={32} color={tema.colorPrimario} />
              <UI.Etiqueta>{MEITI.t('loading_catalog', null, 'Cargando catálogo...')}</UI.Etiqueta>
            </div>
          ) : registros.length === 0 ? (
            <UI.EstadoVacio icono="fa-folder-open" mensaje={MEITI.t('empty_catalog', null, 'No hay registros en este catálogo todavía.')} />
          ) : (
            <UI.TablaDatos 
              columnas={obtenerColumnas()} 
              datos={registros} 
              claveId="id" 
              onEditar={abrirEdicion} 
              onBorrar={(fila) => borrar(fila.id)} 
            />
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}
